let panels = [...stack.children].filter(
  (panel) => panel.matches('[data-panel-id]') && !panel.hidden,
);
const exclusivePanel = panels.find(
  (panel) => panel.dataset.railExclusive !== undefined && !panel.classList.contains('collapsed'),
);
if (exclusivePanel) panels = [exclusivePanel];
